<?php
declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';if(!v700_module_enabled('transport')){http_response_code(404);exit('Transport module is disabled for this tenant.');}$q=trim((string)($_GET['q']??''));$tripsSql="SELECT t.*,r.name route_name,r.origin,r.destination,o.name operator_name,v.title vehicle_title,v.registration_no FROM transport_trips_v700 t JOIN transport_routes_v700 r ON r.id=t.route_id AND r.tenant_id=t.tenant_id LEFT JOIN transport_operators_v700 o ON o.id=r.operator_id LEFT JOIN transport_vehicles_v700 v ON v.id=t.vehicle_id WHERE t.tenant_id=? AND t.status IN ('scheduled','boarding') AND t.departure_at>=DATE_SUB(NOW(),INTERVAL 2 HOUR)";$params=[v700_tid()];if($q!==''){$tripsSql.=' AND (r.origin LIKE ? OR r.destination LIKE ? OR r.name LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}$tripsSql.=' ORDER BY t.departure_at ASC LIMIT 40';$trips=v700_rows($tripsSql,$params);$routes=v700_rows("SELECT r.*,o.name operator_name FROM transport_routes_v700 r LEFT JOIN transport_operators_v700 o ON o.id=r.operator_id WHERE r.tenant_id=? AND r.status='active' ORDER BY r.id DESC LIMIT 12",[v700_tid()]);$st=v700_transport_stats();v700_track('transport','browse');v700_public_header('Transport, Ride & Delivery Network','Bus trips, routes, rides, taxis and delivery in one tenant-aware network.','transport');?>
<main><section class="v700-hero"><div class="v700-shell v700-hero-grid"><div><span class="v700-kicker">↔ CITY MOBILITY</span><h1>Book a trip. Request a ride. Send a delivery.</h1><p>One transport network for local bus routes, vans, rickshaws, taxis, bikes and city deliveries — all managed inside the current ShahkotPK tenant.</p><div class="v700-actions"><a class="v700-btn primary" href="#trips">Find Trip</a><a class="v700-btn secondary" href="/ride.php">Request Ride</a><a class="v700-btn secondary" href="/delivery.php">Send Parcel</a></div></div><div class="v700-orbit"><div class="core">↔</div><div class="sat s1"><b><?=$st['operators']?></b><span>Operators</span></div><div class="sat s2"><b><?=$st['vehicles']?></b><span>Vehicles</span></div><div class="sat s3"><b><?=$st['trips']?></b><span>Trips</span></div><div class="sat s4"><b><?=$st['rides']?></b><span>Active Rides</span></div></div></div></section><section class="v700-section soft" id="trips"><div class="v700-shell"><div class="v700-head"><div><h2>Upcoming trips</h2><p>Scheduled passenger transport with fare and seat visibility.</p></div><a class="v700-btn ghost" href="/transport-account.php">My Travel</a></div><form class="v700-filter"><input name="q" value="<?=e($q)?>" placeholder="Origin, destination or route..."><button class="v700-btn primary">Search Trips</button></form><div class="v700-list"><?php foreach($trips as $t):?><div class="v700-row"><i>🚌</i><span><b><?=e($t['origin'])?> → <?=e($t['destination'])?></b><small><?=e($t['operator_name']?:'City transport')?> · <?=e(date('d M, h:i A',strtotime($t['departure_at'])))?> · <?=max(0,(int)$t['available_seats'])?> seats</small></span><strong><?=v700_money((float)$t['fare'])?></strong><a class="v700-btn primary" href="/transport-book.php?trip=<?=(int)$t['id']?>">Book</a></div><?php endforeach;?><?php if(!$trips):?><div class="v700-empty">No scheduled trips match this search.</div><?php endif;?></div></div></section><section class="v700-section white"><div class="v700-shell"><div class="v700-head"><div><h2>Popular routes</h2><p>Tenant-managed local and intercity routes.</p></div></div><div class="v700-grid"><?php foreach($routes as $r):?><div class="v700-card"><div class="icon">🛣</div><h3><?=e($r['origin'])?> → <?=e($r['destination'])?></h3><p><?=e($r['operator_name']?:'Transport operator')?> · <?=e($r['estimated_minutes']?($r['estimated_minutes'].' min'):'Schedule varies')?></p><b>From <?=v700_money((float)$r['base_fare'])?></b></div><?php endforeach;?></div></div></section></main><?php v700_public_footer(); ?>
